int parse_national_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int processed = 0;
    while (processed < len && p[processed] != 0x00) {
        unsigned char byte = p[processed];
        unsigned char facility_type = (byte >> 6) & 0x03;

        switch (facility_type) {
            case 0x00: // Random Value
                facilities->random_value = p[processed + 1];
                processed += 2;
                break;
            case 0x01: // Source Digipeater
                for (int i = 0; i < 6; i++) {
                    facilities->source_call[i] = p[processed + 1 + i];
                }
                processed += 7;
                break;
            case 0x02: // Destination Digipeater
                for (int i = 0; i < 6; i++) {
                    facilities->dest_call[i] = p[processed + 1 + i];
                }
                processed += 7;
                break;
            case 0x03: // Failure Call
                for (int i = 0; i < 6; i++) {
                    facilities->failure_call[i] = p[processed + 1 + i];
                }
                processed += 7;
                break;
            default:
                // Skip unknown facility type
                processed += 1;
        }
    }

    // Increment for the termination byte
    if (processed < len && p[processed] == 0x00) {
        processed += 1;
    }

    return processed;
}

int parse_national_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int i;
    unsigned char *q = p;
    unsigned char *end = p + len;
    int count = 0;

    while (q < end && *q != 0x00) {
        unsigned char type = (*q >> 6) & 0x03;
        unsigned char subtype = *q & 0x3F;
        int length = 1;

        switch (type) {
            case 0x00:
                facilities->random = (int) (subtype);
                break;
            case 0x01:
                facilities->source_digipeaters = (int) (subtype);
                break;
            case 0x02:
                facilities->dest_digipeaters = (int) (subtype);
                break;
            case 0x03:
                facilities->failure_call = (int) (subtype);
                break;
            default:
                break;
        }

        length += subtype;
        q += length;
        count += length;
    }

    return count;
}

int parse_national_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int processed = 0;

    while (processed < len && p[processed] != 0x00) {
        unsigned char byte = p[processed++];
        unsigned char facility_type = (byte >> 6) & 0x03;

        switch (facility_type) {
            case 0x00: /* Random value facility */
                facilities->random_value = p[processed++];
                break;
            case 0x01: /* Source Digipeater */
                facilities->source_digipeater[facilities->num_source_digipeaters++] = p[processed++];
                break;
            case 0x02: /* Destination Digipeater */
                facilities->dest_digipeater[facilities->num_dest_digipeaters++] = p[processed++];
                break;
            case 0x03: /* Failure call or address */
                facilities->failure_call[facilities->num_failure_calls++] = p[processed++];
                break;
            default:
                /* Skip unknown facility type */
                break;
        }
    }

    return processed;
}

int parse_national_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int processed = 0;
    unsigned char *end = p + len;

    while (p < end && *p != 0x00) {
        unsigned char byte = *p++;
        unsigned int facility_type = (byte >> 6) & 0x03;

        switch (facility_type) {
            case 0x00: // Random value
                facilities->random_value = (byte & 0x3F);
                facilities->has_random_value = 1;
                break;
            case 0x01: // Source digipeater
                facilities->source_digipeater[facilities->num_source_digipeaters++] = (byte & 0x3F);
                break;
            case 0x02: // Destination digipeater
                facilities->dest_digipeater[facilities->num_dest_digipeaters++] = (byte & 0x3F);
                break;
            case 0x03: // Failure call
                facilities->failure_call[facilities->num_failure_calls++] = (byte & 0x3F);
                break;
            default:
                // Reserved or unknown, skip
                break;
        }

        processed++;
    }

    if (p < end && *p == 0x00) {
        p++;
        processed++;
    }

    return processed;
}

int parse_national_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int processed = 0;
    unsigned char *end = p + len;

    while (p < end && *p != 0x00) {
        unsigned char byte = *p++;
        int facility_type = (byte >> 6) & 0x03;

        switch (facility_type) {
            case 0x00:
                // Random value facility
                facilities->random_value = byte & 0x3F;
                break;
            case 0x01:
                // Source digipeater
                facilities->source_digipeater[facilities->num_source_digipeaters++] = byte & 0x3F;
                break;
            case 0x02:
                // Destination digipeater
                facilities->dest_digipeater[facilities->num_dest_digipeaters++] = byte & 0x3F;
                break;
            case 0x03:
                // Failure call or address
                if ((byte & 0x20) == 0x00) {
                    // Failure call
                    facilities->failure_call[facilities->num_failure_calls++] = byte & 0x1F;
                } else {
                    // Address
                    facilities->address[facilities->num_addresses++] = byte & 0x1F;
                }
                break;
            default:
                // Invalid facility type, skip
                break;
        }

        processed++;
    }

    return processed;
}
